        return replayIfPresent(OP_PUBLISH, requestKey,
                preHash != null ? preHash : tryPublishHash(scheduleKey, operator))
                .orElseThrow(() -> conflict("IDEMPOTENT_KEY_REUSED",
                        "requestKey 并发冲突且无法重放: " + requestKey));
